<?php
final class JsonRepository {
 private string $file; private array $entities;
 public function __construct(array $entities){$this->entities=$entities;$dir=getenv('SIGJ_STORAGE_PATH')?:dirname(__DIR__,2).DIRECTORY_SEPARATOR.'sigj-data';if(!is_dir($dir)&&!mkdir($dir,0770,true)&&!is_dir($dir))throw new RuntimeException('Não foi possível criar o armazenamento local.');$this->file=$dir.DIRECTORY_SEPARATOR.'records.json';if(!is_file($this->file))$this->seed();$this->migrateRolesAndOwners();}
 private function seed():void{$data=[];foreach($this->entities as $key=>$entity)$data[$key]=[];$data['clientes']=[['id'=>'CL-001','nome'=>'Marta Almeida','email'=>'marta.almeida@email.ao','telefone'=>'+244 923 410 201','endereco'=>'Luanda'],['id'=>'CL-002','nome'=>'Paulo Domingos','email'=>'paulo.domingos@email.ao','telefone'=>'+244 923 410 202','endereco'=>'Benguela'],['id'=>'CL-003','nome'=>'Ana Cristina','email'=>'ana.cristina@email.ao','telefone'=>'+244 923 410 203','endereco'=>'Huambo']];$data['processos']=[['id'=>'PR-0246','cliente_id'=>'CL-001','numero'=>'2026/0246','tipo'=>'Regularização documental','descricao'=>'Apoio à documentação e encaminhamento.','estado'=>'Em andamento','data_abertura'=>'2026-11-08'],['id'=>'PR-0245','cliente_id'=>'CL-002','numero'=>'2026/0245','tipo'=>'Apoio à empregabilidade','descricao'=>'Preparação para inserção profissional.','estado'=>'Pendente','data_abertura'=>'2026-11-06'],['id'=>'PR-0244','cliente_id'=>'CL-003','numero'=>'2026/0244','tipo'=>'Acompanhamento social','descricao'=>'Acompanhamento social individual.','estado'=>'Concluído','data_abertura'=>'2026-11-03']];$data['supervisores']=[['id'=>'SV-012','nome'=>'João Manuel','email'=>'joao.manuel@sigj.ao','telefone'=>'+244 923 111 120','especialidade'=>'Psicologia'],['id'=>'SV-011','nome'=>'Teresa Neto','email'=>'teresa.neto@sigj.ao','telefone'=>'+244 923 111 121','especialidade'=>'Serviço social']];$data['estagiarios']=[['id'=>'ES-032','supervisor_id'=>'SV-011','nome'=>'Lina Pedro','email'=>'lina.pedro@email.ao','telefone'=>'+244 923 232 032','instituicao'=>'Universidade Agostinho Neto','estado'=>'Em andamento']];$data['vagas']=[['id'=>'VG-018','titulo'=>'Técnico de projectos','descricao'=>'Apoio a iniciativas juvenis.','requisitos'=>'Licenciatura e experiência.','data_abertura'=>'2026-11-05','estado'=>'Aberta'],['id'=>'VG-017','titulo'=>'Assistente administrativo','descricao'=>'Gestão documental e apoio administrativo.','requisitos'=>'Ensino médio.','data_abertura'=>'2026-11-01','estado'=>'Aberta']];$data['candidatos']=[['id'=>'CA-084','nome'=>'Carlos Mário','email'=>'carlos.mario@email.ao','telefone'=>'+244 923 555 084','formacao'=>'Gestão de empresas','vaga_ids'=>['VG-018']],['id'=>'CA-083','nome'=>'Beatriz João','email'=>'beatriz.j@email.ao','telefone'=>'+244 923 555 083','formacao'=>'Informática','vaga_ids'=>['VG-017']]];$data['prazos']=[['id'=>'PZ-021','processo_id'=>'PR-0246','descricao'=>'Entregar documentação','data_limite'=>'2026-11-12','estado'=>'Próximo'],['id'=>'PZ-020','processo_id'=>'PR-0245','descricao'=>'Validar candidatura','data_limite'=>'2026-11-08','estado'=>'Vencido']];$data['_activity']=[['at'=>date(DATE_ATOM),'actor'=>'Sistema','action'=>'Dados iniciais criados','entity'=>'SIGJ','record'=>'']];$data['utilizadores']=[['id'=>'UT-008','nome'=>'Administrador SIGJ','email'=>'admin@sigj.ao','password'=>password_hash('Sigj@2026',PASSWORD_DEFAULT),'perfil'=>'Administrador','supervisor_id'=>'','active'=>'Activo'],['id'=>'UT-007','nome'=>'Teresa Neto','email'=>'teresa.neto@sigj.ao','password'=>password_hash('Sigj@2026',PASSWORD_DEFAULT),'perfil'=>'Supervisor','supervisor_id'=>'SV-011','active'=>'Activo'],['id'=>'UT-006','nome'=>'Rui Gestor','email'=>'gestor@sigj.ao','password'=>password_hash('Sigj@2026',PASSWORD_DEFAULT),'perfil'=>'Gestor','supervisor_id'=>'','active'=>'Activo']];$this->write($data);}
 private function migrateRolesAndOwners():void{$data=$this->read();$changed=false;$supervisorUsers=[];foreach($data['utilizadores']??[] as $i=>$user){if(!empty($user['supervisor_id']))$supervisorUsers[$user['supervisor_id']]=$user['id']??'';}foreach(['clientes','processos','candidatos','prazos','vagas','supervisores','estagiarios'] as $entity){foreach($data[$entity]??[] as $i=>$row){$owner=$row['_owner_id']??'';if($owner===''){$owner=match($entity){'supervisores'=>'UT-008','estagiarios'=>$supervisorUsers[$row['supervisor_id']??'']??'UT-008','vagas'=>'UT-006',default=>'UT-006'};$changed=true;}if(($data[$entity][$i]['_owner_id']??'')!==$owner)$data[$entity][$i]['_owner_id']=$owner;if($entity==='estagiarios'&&empty($data[$entity][$i]['estado'])){$data[$entity][$i]['estado']='Em andamento';$changed=true;}}}foreach(['clientes','processos','supervisores','estagiarios','candidatos','vagas','prazos'] as $entity){foreach($data[$entity]??[] as $i=>$row){if(!array_key_exists('ativo',$row)){$data[$entity][$i]['ativo']=true;$changed=true;}}}if($changed)$this->write($data);}
 private function read():array{$raw=file_get_contents($this->file);$data=json_decode($raw?:'{}',true);return is_array($data)?$data:[];}
 private function write(array $data):void{$tmp=$this->file.'.tmp';if(file_put_contents($tmp,json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX)===false||!rename($tmp,$this->file))throw new RuntimeException('Não foi possível guardar os dados.');}
 public function all(string $entity):array{return $this->read()[$entity]??[];}
 public function find(string $entity,string $id):?array{foreach($this->all($entity) as $row)if(($row['id']??'')===$id)return $row;return null;}
 public function save(string $entity,array $record,?string $id=null):array{$data=$this->read();$rows=$data[$entity]??[];if($id!==null){$found=false;foreach($rows as $i=>$row)if(($row['id']??'')===$id){$record['id']=$id;$rows[$i]=$record;$found=true;break;}if(!$found)throw new RuntimeException('O registo já não existe.');}else{$num=1;foreach($rows as $row){if(preg_match('/-(\d+)$/',$row['id']??'',$m))$num=max($num,(int)$m[1]+1);}$record['id']=$this->entities[$entity]['prefix'].'-'.str_pad((string)$num,3,'0',STR_PAD_LEFT);$rows[]=$record;}$data[$entity]=$rows;$this->write($data);return $record;}
 public function log(string $actor,string $action,string $entity,string $record=''):void{$data=$this->read();$data['_activity']??=[];array_unshift($data['_activity'],['at'=>date(DATE_ATOM),'actor'=>$actor,'action'=>$action,'entity'=>$entity,'record'=>$record]);$data['_activity']=array_slice($data['_activity'],0,200);$this->write($data);}
 public function activities(int $limit=8):array{return array_slice($this->read()['_activity']??[] ,0,$limit);}
 public function delete(string $entity,string $id):bool{throw new LogicException('A eliminação permanente de registos está desativada. Altere o estado do registo para Inactivo.');}
}
